function StackQuestionVisual({ prompt }) {
  const [items, setItems] = useState(() => (prompt.match(/\d+/g) || []).slice(-3).map(Number));
  const [status, setStatus] = useState("READ FROM BOTTOM → TOP");
  function push() { if (items.length >= 5) { setStatus("OVERFLOW — STACK IS FULL"); return; } const value = Math.floor(Math.random() * 90) + 10; setItems((currentItems) => [...currentItems, value]); setStatus(`PUSHED ${value} TO TOP`); }
  function pop() { if (!items.length) { setStatus("UNDERFLOW — STACK IS EMPTY"); return; } const value = items[items.length - 1]; setItems((currentItems) => currentItems.slice(0, -1)); setStatus(`POPPED ${value} FROM TOP`); }
  return <div className="question-stack-lab"><div><small>LIVE STACK VISUALIZER</small><b>Which item leaves first?</b><p>In LIFO, the newest top item is removed first.</p><code>{status}</code><div><button onClick={push} type="button">+ PUSH</button><button onClick={pop} type="button" disabled={!items.length}>− POP</button></div></div><div className="question-stack"><span>TOP ↓</span><div>{[...items].reverse().map((item, index) => <i key={`${item}-${items.length - index}`}>{item}</i>)}</div><strong>BOTTOM</strong></div></div>;
}

